CREATE TABLE IF NOT EXISTS virtual_accounts (virtual_account_id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES users(owner_id) ON DELETE CASCADE, label TEXT NOT NULL, opening_cash NUMERIC(20,4) NOT NULL CHECK(opening_cash>=0), cash_balance NUMERIC(20,4) NOT NULL CHECK(cash_balance>=0), mode TEXT NOT NULL DEFAULT 'synthetic' CHECK(mode='synthetic'), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(owner_id,label));
CREATE TABLE IF NOT EXISTS virtual_orders (order_id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES users(owner_id) ON DELETE CASCADE, virtual_account_id UUID NOT NULL REFERENCES virtual_accounts(virtual_account_id), instrument_id UUID NOT NULL REFERENCES instruments(instrument_id), side TEXT NOT NULL CHECK(side IN('buy','sell')), quantity NUMERIC(20,4) NOT NULL CHECK(quantity>0), limit_price NUMERIC(20,4) NOT NULL CHECK(limit_price>0), status TEXT NOT NULL CHECK(status IN('open','cancelled','filled')), reserved_cash NUMERIC(20,4) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
